const survives = (liveNeighborCount: number): boolean =>
  liveNeighborCount === 2 || liveNeighborCount === 3;

const isBorn = (liveNeighborCount: number): boolean => liveNeighborCount === 3;

const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
  liveCells.some((other) => isSameCell(cell, other));

const cellKey = ([x, y]: Cell): string => `${x},${y}`;

const OFFSETS = [-1, 0, 1];

const cellWithNeighbors = ([x, y]: Cell): Cell[] =>
  OFFSETS.flatMap((dx) => OFFSETS.map((dy): Cell => [x + dx, y + dy]));

const uniqueCells = (cells: Cell[]): Cell[] => [
  ...new Map(cells.map((cell) => [cellKey(cell), cell])).values(),
];

const candidateCells = (liveCells: Cell[]): Cell[] =>
  uniqueCells(liveCells.flatMap(cellWithNeighbors));

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return candidateCells(liveCells).filter((cell) => {
    const liveNeighborCount = countLiveNeighbors(cell, liveCells);
    return isAlive(cell, liveCells)
      ? survives(liveNeighborCount)
      : isBorn(liveNeighborCount);
  });
}
